/// <summary>
/// Apply filter on Order extract screen if any of the values is supplied
/// </summary>
public void filterSelectionChanged()
{
    if(filterSite.text() || filterInventLocationId.text() || filterSalesShippingDateConfirmed.text() || filterMETRoute.text())
    {
        this.datasourceApplyFilter();
    }
}

    /// <summary>
    /// Execute and manage the filter pane and quick filter control queries.
    /// </summary>
    protected void datasourceApplyFilter()
    {
        QueryBuildDataSource qbdsOrderExtractScreen = SalesTable_ds.query().dataSourceTable(tableNum(SalesTable));
        QueryBuildRange siteRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, InventSiteId));
        siteRange.value(filterSite.text());

        QueryBuildRange inventLocationIdRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, InventLocationId));
        inventLocationIdRange.value(filterInventLocationId.text());

        QueryBuildRange salesShippingDateConfirmedRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, ShippingDateConfirmed));
        salesShippingDateConfirmedRange.value(filterSalesShippingDateConfirmed.text());

        QueryBuildRange routeRange = SysQuery::findOrCreateRange(qbdsOrderExtractScreen, fieldNum(SalesTable, METRoute));
        routeRange.value(filterMETRoute.text());

        SalesTable_ds.executeQuery();
    }

        /// <summary>
        /// set only sales orders which are confirmed or above status
        /// </summary>
        public void init()
        {
            super();

            QueryBuildDataSource qbdsOrderExtrect = SalesTable_ds.query().dataSourceTable(tableNum(SalesTable));
            QueryBuildRange SalesStatusRange = SysQuery::findOrCreateRange(qbdsOrderExtrect, fieldNum(SalesTable, SalesStatus));
            SalesStatusRange.value(strFmt('%1,%2,%3', enum2Str(SalesStatus::Backorder), enum2Str(SalesStatus::Delivered),
                                                        enum2Str(SalesStatus::Invoiced)));


           }

    /// <summary>
    /// filter Sales order data based on Route
    /// </summary>
    /// <returns>boolean value</returns>
    public boolean modified()
    {
        boolean ret;

        ret = super();
        element.filterSelectionChanged();

        return ret;
    }

